head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > tooltipDisplayColumn]<br/>tooltipDisplay=true 일때 툴팁을 표시할 Column 을 설정합니다.",
    "validation" : [
        "콤마(',')를 구분자로 툴팁을 표시할 Column 의 ID 를 한 개 이상 설정하면, 해당 Column 의 Cell 만 잘림 시 마우스 오버 툴팁을 표시합니다.",
        "tooltipDisplayColumn 에 설정되지 않은 Column 의 Cell 은 값이 잘려도 마우스 오버 시 툴팁이 표시되지 않습니다.",
        "속성값을 설정하지 않으면 '' 로 적용되어 전체 Column 에서 툴팁이 표시됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_tooltipDisplayColumn 초기값 보관 (일부 Column 만 지정한 케이스로 시작)
    scwin.gVar = { "cTooltipDisplayColumn": "col_a,col_c" };

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - tooltipDisplayColumn 검증용 커스텀 GridView 를 인라인 정의로 생성한다.
//  - 고정 전제 : tooltipDisplay=true, 모든 Body Column 이 잘리는 긴 값(width 좁음)을 가짐.
//  - 컬럼 구성 (모두 긴 text 값 -> 잘림)
//      col_a : 긴 값 text  -> 지정 케이스(col_a,col_c) 에서 툴팁 표시
//      col_b : 긴 값 text  -> 지정 케이스에서 미표시(미지정 Column)
//      col_c : 긴 값 text  -> 지정 케이스에서 툴팁 표시
//      col_d : 긴 값 text  -> 지정 케이스에서 미표시(미지정 Column)
//  - 미설정('') 케이스에서는 col_a~col_d 전체에서 잘림 시 툴팁 표시
scwin.comp_init = async function () {
    // con 현재값 반영 (Target 재생성 버튼이 comp_init 재호출)
    scwin.gVar.cTooltipDisplayColumn = con_tooltipDisplayColumn.getValue();   // "col_a,col_c" / "col_b" / "" (미설정)

    // 동적 생성용 네임스페이스 (페이지 scope 에서 scwin.strNameSpace 가 비어있을 수 있어 로컬 정의)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    let dcMsg = (scwin.gVar.cTooltipDisplayColumn === "") ? "미설정('' -> 전체 Column)" : scwin.gVar.cTooltipDisplayColumn;
    $c.gcm.createLabel('label="[전제] tooltipDisplay=true / 4개 Column(col_a~col_d) 모두 잘리는 긴 값. 현재 tooltipDisplayColumn=' + dcMsg + '.\n[절차] 각 Column 의 Body Cell 에 마우스를 오버하여 툴팁을 표시한 뒤 해당 Cell 을 클릭하면 표시된 툴팁 정보가 출력됩니다.\n[확인] 지정 케이스: 지정된 Column 의 Cell 만 툴팁 표시, 그 외 Column 은 미표시. 미설정: 전체 Column 의 Cell 에서 툴팁 표시."', '', 'label1');

    // dataList 생성 (커스텀 컬럼에 맞춘 데이터 바인딩)
    //  - dataList 는 $p.dynamicCreate 가 아닌 $p.data.create 로 생성한다.
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col_a" name="col_a"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_b" name="col_b"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_c" name="col_c"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_d" name="col_d"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    scwin.dlt_bind.setJSON([
        { "col_a": "서울특별시 강남구 테헤란로 152 강남파이낸스센터 23층", "col_b": "프리미엄 무선 노이즈캔슬링 헤드폰 블랙 에디션", "col_c": "기업금융사업본부 디지털전략기획팀 책임매니저", "col_d": "2026년 상반기 정기 거래 실적 우수 고객 안내문" },
        { "col_a": "부산광역시 해운대구 센텀중앙로 79 센텀사이언스파크 18층", "col_b": "스마트 4K UHD 게이밍 모니터 27인치 곡면형", "col_c": "개인고객사업본부 영업지원팀 선임주임", "col_d": "2026년 하반기 신규 상품 출시 일정 사전 공지" }
    ], false);

    // tooltipDisplayColumn : con 값에 따라 설정/미설정 (미설정 시 속성 자체를 제외하여 기본값 '' 동작 확인)
    let tooltipDisplayColumnAttr = (scwin.gVar.cTooltipDisplayColumn === "") ? "" : 'tooltipDisplayColumn="' + scwin.gVar.cTooltipDisplayColumn + '" ';

    // 커스텀 GridView 인라인 정의
    //  - 좁은 컬럼 폭(width=70) + 긴 Cell 값으로 잘림(truncation) 을 유도 (tooltipDisplay 의 '잘림 시 표시' 전제 충족)
    let strTarget = '<w2:gridView ' + ns + ' tooltipDisplay="true" ' + tooltipDisplayColumnAttr + 'dataList="data:dlt_bind" id="" style="width:700px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="70" inputType="text" id="col_a" value="주소"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col_b" value="상품명"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col_c" value="소속"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col_d" value="안내문"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="70" inputType="text" id="col_a" dataList="col_a"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col_b" dataList="col_b"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col_c" dataList="col_c"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col_d" dataList="col_d"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    let grp_comp = document.querySelector('.tc_group_basic');
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 클릭 시 현재 표시된 툴팁 정보를 return 영역에 출력하기 위한 클릭 리스너 설치 (재생성 후에도 재부착)
    scwin.attachTooltipClick();
};



// Body Cell 클릭 시 "현재 표시된" 툴팁 정보를 return 영역에 출력
//  - 셀에 마우스를 오버해 툴팁(잘린 Cell 값)이 표시된 상태에서 그 영역을 클릭하면 호출된다.
//  - 타이밍 주의 : 엔진은 셀 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫는다(display:none).
//    따라서 클릭의 "캡처(capture) 단계" 리스너로 잡아야 툴팁이 아직 살아있어 정상 출력된다.
//  - 리스너를 그리드 DOM 엘리먼트에 걸어 Cell 클릭을 커버한다.
//  - 마우스오버만 해서는 출력되지 않으며, 클릭 시점에 현재 hover 로 표시된 툴팁 값이 캡처된다.
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function () { $c.gcm.getTooltipInfo(wf_body_bottom); };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);
}
